// Datos que manda la IA (trigger). El teléfono sale de acá: la salida del nodo LEADS no trae `tel`.
const item = $('When Executed by Another Workflow').first().json;
const resumen = (item.resumen || "").toLowerCase();

let origen = item.origen || null;

if (!origen) {
  if (resumen.includes("kyc")) {
    origen = "FZB3EIXK37ZREQZGG";
  } else if (resumen.includes("jetour")) {
    origen = "FZB30EQIWMBYNOOAO";
  }
}

// -------------------------------------------------
// Normalizar teléfono
// -------------------------------------------------
const tel = String(item.tel || "").replace(/\D/g, "");

let numero = tel;

if (numero.startsWith("549")) {
  numero = numero.slice(3);
} else if (numero.startsWith("54")) {
  numero = numero.slice(2);
}

// -------------------------------------------------
// RUTEO
// SALTA: únicamente 387
// TUCUMAN: todo el resto (si no coincide ningún prefijo)
// -------------------------------------------------
let claveRuteo = "TUCUMAN";

if (numero.startsWith("387")) {
  claveRuteo = "SALTA";
}

// -------------------------------------------------
// GrupoCaptura siempre coincide con el ruteo
// Se ignora el GrupoCaptura anterior
// -------------------------------------------------
const grupoCaptura = claveRuteo;

return [{
  json: {
    ...item,
    origen,
    GrupoCaptura: grupoCaptura,
    claveRuteo
  }
}];

